<script setup>
import { ref } from 'vue'
import { save, state } from '../stores/lexigo'
const file = ref(); const status = ref(''); const backup = () => { const blob = new Blob([JSON.stringify(state, null, 2)], { type: 'application/json' }); const link = document.createElement('a'); link.href = URL.createObjectURL(blob); link.download = `lexigo-backup-${new Date().toISOString().slice(0, 10)}.json`; link.click(); URL.revokeObjectURL(link.href); status.value = 'Backup downloaded.' }; const restore = () => { const selected = file.value?.files?.[0]; if (!selected) return; const reader = new FileReader(); reader.onload = () => { try { Object.assign(state, JSON.parse(reader.result)); save(); status.value = 'Backup restored successfully.' } catch { status.value = 'That file is not a valid LexiGo backup.' } }; reader.readAsText(selected) }
</script>
<template><section class="mx-auto max-w-2xl px-5 py-14"><p class="text-[11px] font-bold tracking-[.15em] text-lexi">SETTINGS</p><h1 class="mt-2 font-display text-5xl font-bold">Your learning space</h1><article class="mt-7 rounded-2xl border border-slate-200 bg-white p-6"><h2 class="font-display text-2xl font-bold">Teaching mode</h2><p class="mt-2 text-sm text-slate-500">Choose the tone for your LexiGo experience.</p><div class="mt-4 inline-flex rounded-xl bg-violet-100 p-1"><button class="rounded-lg px-4 py-2 text-sm font-bold" :class="state.mode === 'kids' ? 'bg-white text-lexi shadow-sm' : 'text-slate-500'" @click="state.mode = 'kids'; save()">🌈 Kids</button><button class="rounded-lg px-4 py-2 text-sm font-bold" :class="state.mode === 'adult' ? 'bg-white text-lexi shadow-sm' : 'text-slate-500'" @click="state.mode = 'adult'; save()">✦ Adult</button></div></article><article class="mt-4 rounded-2xl border border-slate-200 bg-white p-6"><h2 class="font-display text-2xl font-bold">Sound</h2><label class="mt-4 flex items-center gap-3 text-sm font-bold"><input v-model="state.sound" class="h-5 w-5 accent-lexi" type="checkbox" @change="save"> Pronunciation playback</label></article><article class="mt-4 rounded-2xl border border-slate-200 bg-white p-6"><h2 class="font-display text-2xl font-bold">Backup & restore</h2><p class="mt-2 text-sm leading-6 text-slate-500">Your data is stored in this browser. Keep a backup when you need it.</p><div class="mt-4 flex flex-wrap gap-3"><button class="rounded-xl bg-lexi px-4 py-3 text-sm font-bold text-white" @click="backup">Download backup</button><input ref="file" class="max-w-60 text-sm" type="file" accept="application/json" @change="restore"></div><p v-if="status" class="mt-3 text-sm font-bold text-emerald-600">{{ status }}</p></article></section></template>
